import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadKalighatData(){const e=readFileSync(resolve(__dirname,"../../kalighat-painting-showcase/kalighat-data.js"),"utf-8");return new Function(e+"\nreturn { KALIGHAT_INFO, HISTORY_CHAPTERS, BRUSHWORK_STEPS, THEMES, ARTIST_COMMUNITY, GALLERY_IMAGES, REFERENCES };")()}describe("Kalighat Painting Showcase — Data Tests",()=>{let e;beforeAll(()=>{e=loadKalighatData()}),describe("KALIGHAT_INFO metadata",()=>{it("contains correct Kalighat metadata",()=>{expect(e.KALIGHAT_INFO.id).toBe("kalighat-painting"),expect(e.KALIGHAT_INFO.title).toContain("Kalighat"),expect(e.KALIGHAT_INFO.originRegion).toContain("Kolkata"),expect(e.KALIGHAT_INFO.signatureStyle).toContain("stroke")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.KALIGHAT_INFO.quickStats)).toBe(!0),expect(e.KALIGHAT_INFO.quickStats.length).toBe(6)})}),describe("HISTORY_CHAPTERS & BRUSHWORK_STEPS",()=>{it("contains history chapters and brushwork steps",()=>{expect(Array.isArray(e.HISTORY_CHAPTERS)).toBe(!0),expect(e.HISTORY_CHAPTERS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.BRUSHWORK_STEPS)).toBe(!0),expect(e.BRUSHWORK_STEPS.length).toBeGreaterThanOrEqual(4)})}),describe("THEMES",()=>{it("contains divine and social-satire themes",()=>{expect(Array.isArray(e.THEMES)).toBe(!0),expect(e.THEMES.length).toBeGreaterThanOrEqual(4),expect(e.THEMES.some(e=>"Divine"===e.category)).toBe(!0),expect(e.THEMES.some(e=>"Social Satire"===e.category)).toBe(!0)})}),describe("ARTIST_COMMUNITY",()=>{it("contains artist community details",()=>{expect(e.ARTIST_COMMUNITY.title).toBeDefined(),expect(e.ARTIST_COMMUNITY.description).toContain("Kalighat")})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});